<?php require __DIR__.'/../config/db.php'; $b=body(); if($_SERVER['REQUEST_METHOD']!=='POST')out(['error'=>'Method']);$st=$pdo->prepare('SELECT * FROM admin WHERE username=?');$st->execute([$b['username']??'']);$a=$st->fetch();if(!$a||!password_verify($b['password']??'',$a['password_hash'])){http_response_code(401);out(['error'=>'Login gagal']);}out(['token'=>hash_hmac('sha256',$a['id'].'|'.$a['username'],$config['app_key']),'admin'=>['id'=>$a['id'],'username'=>$a['username']]]);
